def classify_waste_costs(apps, schema_editor):
    """Derive labels only from explicit retained evidence; preserve audit snapshots."""
    sections = (
        apps.get_model("bills", "BillingSection")
        .objects.using(schema_editor.connection.alias)
        .filter(service="waste", subcategory="")
        .prefetch_related("usages")
    )
    for section in sections:
        texts = [(section.period_evidence or {}).get("text", "")]
        texts.extend((usage.evidence or {}).get("text", "") for usage in section.usages.all())
        categories = set()
        for text in texts:
            if re.match(r"^(?:Slamavskiljare|Slamtömning|Tank emptying)\b", text.strip(), re.I):
                categories.add("tank_emptying")
            elif re.match(
                r"^(?:Grundavgift permanentbostad|Tömn(?:ing)?\s+(?:Restavfall|Matavfall)"
                r"|Restavfall|Matavfall)\b",
                text.strip(),
                re.I,
            ):
                categories.add("waste_collection")
        if len(categories) == 1:
            sections.filter(pk=section.pk).update(subcategory=next(iter(categories)))


